{
  "type": "object",
  "additionalProperties": true,
  "properties": {
    "id": {
      "type": "string",
      "minLength": 1
    },
    "caption": {
      "type": "string"
    },
    "layout": {
      "oneOf": [
        {
          "type": "string",
          "enum": [
            "header-search-grid-detail"
          ]
