        "$ref": "#/$defs/sectionGroup"
      }
    },
    "markdown": {
      "$ref": "#/$defs/markdownOptions"
    },
    "viewDefReport": {
      "$ref": "#/$defs/viewDefReportOptions"
    },
    "dataSources": {
      "$ref": "#/$defs/dataSources"
    },
    "data_sources": {
      "$ref": "#/$defs/dataSources"
    },
    "virtualData": {
      "$ref": "#/$defs/virtualData"
    },
    "virtual_data": {
      "$ref": "#/$defs/virtualData"
    },
    "writePolicy": {
      "$ref": "#/$defs/writePolicy"
    },
    "write_policy": {
      "$ref": "#/$defs/writePolicy"
    },
    "toolbar": {
      "$ref": "#/$defs/toolbarOptions"
    },
    "fieldTypeSources": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      ]
    },
    "field_type_sources": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      ]
    },
    "typeSources": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      ]
    },
    "type_sources": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      ]
