      "type": "object",
      "additionalProperties": true,
      "description": "Detail Dialog内の配置制御。例: {\"placement\":\"detailFooter\"} で子配列表示後に描画する。",
      "properties": {
        "placement": {
          "type": "string",
          "enum": [
            "detailBody",
            "detailFooter",
            "afterChildGrids"
          ]
        },
        "after": {
          "type": "string",
          "enum": [
            "childGrids"
          ]
        },
        "order": {
          "type": "number"
        }
      }
    },
    "control": {
      "type": "string",
      "enum": [
        "combobox",
        "listbox",
        "radio"
      ]
    },
    "fieldType": {
      "type": "string"
    },
    "field_type": {
      "type": "string"
    },
    "typeRef": {
      "type": "string"
    },
    "type_ref": {
      "type": "string"
    },
    "valueField": {
      "type": "string"
    },
    "value_field": {
      "type": "string"
    },
    "optionValueField": {
      "type": "string"
    },
    "option_value_field": {
      "type": "string"
    },
    "labelField": {
      "type": "string"
    },
    "label_field": {
      "type": "string"
    },
    "optionLabelField": {
      "type": "string"
    },
    "option_label_field": {
      "type": "string"
    }
  },
  "required": [
    "field",
    "caption",
    "type"
  ]
}

